CREATE TABLE IF NOT EXISTS "public"."ambassador_codes" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "profile_id" bigint NOT NULL,
    "code" "text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "tenant_id" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT ("now"() AT TIME ZONE 'utc'::"text") NOT NULL,
    CONSTRAINT "ambassador_codes_profile_id_tenant_id_key" UNIQUE ("profile_id", "tenant_id"),
    CONSTRAINT "ambassador_codes_code_tenant_id_key" UNIQUE ("code", "tenant_id"),
    CONSTRAINT "ambassador_codes_code_upper_check" CHECK ("code" = upper("code"))
);

CREATE INDEX "idx_ambassador_codes_tenant_id" ON "public"."ambassador_codes" USING "btree" ("tenant_id");

ALTER TABLE ONLY "public"."ambassador_codes"
    ADD CONSTRAINT "ambassador_codes_profile_id_fkey" FOREIGN KEY ("profile_id") REFERENCES "public"."profiles"("id") ON UPDATE CASCADE ON DELETE CASCADE;

ALTER TABLE "public"."ambassador_codes" ENABLE ROW LEVEL SECURITY;

CREATE POLICY "tenant_isolation" ON "public"."ambassador_codes" USING (("tenant_id" = ((SELECT current_setting('request.headers'::"text", true))::"json" ->> 'x-tenant-id'::"text")));
